SlaveAct();





Axis1ErrorAlarm :=  AntiRejection1.NCTOPLC.POWERPOSWARN OR AntiRejection1.NCTOPLC.POWERNEGWARN 
     OR AntiRejection1.NCTOPLC.ERRORCODE <>0;


  IF Axis1ErrorAlarm AND g_bPlcResetBuffer THEN
    g_AntiRejection1Reset.Execute := TRUE;
  ELSE
    g_AntiRejection1Reset.Execute := FALSE;   
  END_IF;
